package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplySettings {
    // A dated setting is recorded from its from-date, else from the sheet's today, keeping the values recorded from other dates.
    public void apply(@Val SheetSettings settings, Settings store, Sheets sheets) {
        LocalDate today = sheets.today(settings.sheetId());
        if (settings.clerkLimit() != null) {
            dated(settings, store, today, Settings.CLERK_LIMIT, settings.clerkLimit());
        }
        if (settings.floor() != null) {
            dated(settings, store, today, Settings.FLOOR, settings.floor());
        }
        if (settings.terms() != null) {
            dated(settings, store, today, Settings.TERMS, settings.terms());
        }
        settings.gradeTerms().forEach((grade, days) -> dated(settings, store, today, Settings.gradeTermsKey(grade), days));
        if (settings.latePct() != null) {
            dated(settings, store, today, Settings.LATE_PCT, settings.latePct());
        }
        if (settings.policyDate() != null) {
            store.set(settings.sheetId(), Settings.POLICY_DATE, settings.policyDate());
        }
        if (settings.periodNumberingFrom() != null) {
            store.set(settings.sheetId(), Settings.PERIOD_NUMBERING_FROM, settings.periodNumberingFrom());
        }
        if (settings.cap() != null) {
            dated(settings, store, today, Settings.CAP, settings.cap());
        }
        if (settings.proofThreshold() != null) {
            dated(settings, store, today, Settings.PROOF_THRESHOLD, settings.proofThreshold());
        }
        if (settings.noteThreshold() != null) {
            dated(settings, store, today, Settings.NOTE_THRESHOLD, settings.noteThreshold());
        }
        if (settings.graceDays() != null) {
            store.set(settings.sheetId(), Settings.GRACE_DAYS, settings.graceDays());
        }
        settings.perms().forEach((action, roles) -> store.set(settings.sheetId(), Settings.permKey(action), roles));
    }

    private static void dated(SheetSettings settings, Settings store, LocalDate today, String key, String value) {
        store.set(settings.sheetId(), key, settings.from().getOrDefault(key, today), value);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditSettingChanged {
    // One line per setting saved: the clerk limit, then the floor, then the terms, then each grade's own terms by grade, then the late percent, then the policy date, then the period numbering from-date, then the cap, then the proof threshold, then the note threshold, then the grace days, then each action's permitted roles, in the matrix's order. A dated setting saved with a from-date ends with from=<date>.
    public void audit(@Val SheetSettings settings, ServerHttpConnection connection, Audit audit) {
        if (settings.clerkLimit() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.CLERK_LIMIT, "value=" + settings.clerkLimit(), from(settings, Settings.CLERK_LIMIT)));
        }
        if (settings.floor() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.FLOOR, "value=" + settings.floor(), from(settings, Settings.FLOOR)));
        }
        if (settings.terms() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.TERMS, "value=" + settings.terms(), from(settings, Settings.TERMS)));
        }
        settings.gradeTerms().forEach((grade, days) -> audit.record(dated(settings, connection,
                "key=" + Settings.gradeTermsKey(grade), "value=" + days, from(settings, Settings.gradeTermsKey(grade)))));
        if (settings.latePct() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.LATE_PCT, "value=" + settings.latePct(), from(settings, Settings.LATE_PCT)));
        }
        if (settings.policyDate() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.POLICY_DATE, "value=" + settings.policyDate()));
        }
        if (settings.periodNumberingFrom() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.PERIOD_NUMBERING_FROM, "value=" + settings.periodNumberingFrom()));
        }
        if (settings.cap() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.CAP, "value=" + settings.cap(), from(settings, Settings.CAP)));
        }
        if (settings.proofThreshold() != null) {
            audit.record(dated(settings, connection, "key=" + Settings.PROOF_THRESHOLD, "value=" + settings.proofThreshold(),
                    from(settings, Settings.PROOF_THRESHOLD)));
        }
        if (settings.noteThreshold() != null) {
            audit.record(dated(settings, connection, "key=" + Settings.NOTE_THRESHOLD, "value=" + settings.noteThreshold(),
                    from(settings, Settings.NOTE_THRESHOLD)));
        }
        if (settings.graceDays() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.GRACE_DAYS, "value=" + settings.graceDays()));
        }
        settings.perms().forEach((action, roles) -> audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(),
                Audit.user(connection), "key=" + Settings.permKey(action), "value=" + roles)));
    }

    private static String from(SheetSettings settings, String key) {
        java.time.LocalDate from = settings.from().get(key);
        return from == null ? null : "from=" + from;
    }

    /** A dated setting's line: its key and value, then its from-date when one was given. */
    private static String dated(SheetSettings settings, ServerHttpConnection connection, String key, String value, String from) {
        String line = Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection), key, value);
        return from == null ? line : line + " " + from;
    }
}
package net.officefloor.hq.app.setting;

/** The sheet's settings as the screen sees them, each dated one as it is in force on the sheet's today: the clerk limit with two decimals, "" when there is none, the floor with two decimals, the terms in days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" when there is none (the sheet's today is), and the period numbering from-date as yyyy-MM-dd, "" when it is off, and the terms in force for each grade, in days (its own, or the sheet's terms when it has none), and the cap with two decimals, "" when there is none. {@code dated} is every value recorded for each dated setting, by setting key, by from-date. {@code perms} is the roles each action is permitted to, by action, as a comma separated list, "" for the standing rule. {@code graceDays} is the grace days, "" when they are off. */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, java.util.List<Settings.DatedValue>> dated,
        java.util.Map<String, String> perms, String graceDays) {
}
package net.officefloor.hq.app.setting;

/** The body of the settings being saved, as typed: the clerk limit (blank: no limit) and the floor, the terms and the late percent (each null or blank: left as it is), and the policy date (null: left as it is; blank: none, so the sheet's today), and the period numbering from-date (null: left as it is; blank: off), and the cap, the proof threshold and the note threshold (each null: left as it is; blank: none), and the grace days (null: left as it is; blank: off), and the terms of a grade's own, by grade (each left out, null or blank: left as it is), and the from-date (yyyy-mm-dd) each dated setting saved is recorded from, by setting key (left out or blank: the sheet's today), and the roles each action is permitted to, by action, as a comma separated list (left out or null: left as it is; blank: the standing rule). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String cap, String proofThreshold, String graceDays, String noteThreshold,
        java.util.Map<String, String> gradeTerms, java.util.Map<String, String> from, java.util.Map<String, String> perms) {
}
package net.officefloor.hq.app.setting;

/**
 * The settings of a sheet being saved, each null when it is left as it is: the clerk limit with two decimals,
 * "" for no limit, the floor with two decimals, the terms as a whole number of days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" for none, and the period numbering from-date as yyyy-MM-dd, "" for off, and the cap, the proof threshold and the note threshold, each with two decimals, "" for none, and the grace days as a whole number of days, "" for off.
 * {@code gradeTerms} are the terms of a grade's own being saved, as a whole number of days, by grade (a grade left out is left as it is).
 * {@code perms} are the roles each action is permitted to being saved, by action in {@link Settings#PERM_ACTIONS} order, as a comma separated list, "" for the standing rule.
 * {@code from} is the from-date given for a dated setting, by setting key (a key left out is saved from the sheet's today, and audited without one).
 */
public record SheetSettings(String sheetId, String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom, String cap, String proofThreshold, String graceDays, String noteThreshold,
        java.util.SortedMap<String, String> gradeTerms, java.util.Map<String, java.time.LocalDate> from,
        java.util.Map<String, String> perms) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Map;
import java.util.SortedMap;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");

    // The amounts are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is
    // no limit, unless a floor, terms, late percent or policy date are saved with it, when the clerk limit is left as it is (and null
    // leaves it as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is
    // refused. Blank terms are left as they are; otherwise they must be a whole number of days, 0 or more.
    // A blank late percent is left as it is; otherwise it must be a percent of 0.00 or more, with up to two decimals.
    // A missing policy date is left as it is; a blank one is none (the sheet's today is); otherwise it must be a yyyy-MM-dd date.
    // A grade's own terms are like the terms: blank is left as it is, otherwise a whole number of days, 0 or more,
    // and only a grade (A, B or C) may have them.
    // The period numbering from-date is the same: missing is left as it is, blank is off, otherwise a yyyy-MM-dd date.
    // The cap is missing: left as it is, blank: none, otherwise an amount of 0.00 or more with up to two decimals.
    // The proof threshold is like the cap: missing is left as it is, blank is none, otherwise an amount of 0.00 or more with up to two decimals.
    // The note threshold is like the cap too.
    // The grace days are missing: left as they are, blank: off, otherwise a whole number of days, 0 or more (not dated).
    // An action's permitted roles are missing: left as they are, blank: the standing rule, otherwise clerk or steward, separated by commas.
    // A from-date, given by setting key, is blank (the sheet's today) or a yyyy-MM-dd date, and only a dated setting has one.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest body,
            Out<SheetSettings> settingsOut) throws InvalidSettingException {
        String floor = body == null || body.floor() == null ? "" : body.floor().trim();
        if (!floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
            throw new InvalidSettingException("The floor must be an amount of 0.00 or more, with up to two decimals.");
        }
        String typed = body == null || body.clerkLimit() == null ? null : body.clerkLimit().trim();
        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
        }
        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
        }
        SortedMap<String, String> gradeTerms = new TreeMap<>();
        if (body != null && body.gradeTerms() != null) {
            for (Map.Entry<String, String> entry : body.gradeTerms().entrySet()) {
                String grade = entry.getKey() == null ? "" : entry.getKey().trim();
                String days = entry.getValue() == null ? "" : entry.getValue().trim();
                if (days.isEmpty()) {
                    continue;
                }
                if (!Settings.GRADES.contains(grade)) {
                    throw new InvalidSettingException("Terms can be set only for grade A, B or C.");
                }
                if (!DAYS.matcher(days).matches()) {
                    throw new InvalidSettingException("The terms of grade " + grade + " must be a whole number of days, 0 or more.");
                }
                gradeTerms.put(grade, Integer.toString(Integer.parseInt(days)));
            }
        }
        String latePct = body == null || body.latePct() == null ? "" : body.latePct().trim();
        if (!latePct.isEmpty() && !AMOUNT.matcher(latePct).matches()) {
            throw new InvalidSettingException("The late percent must be a percent of 0.00 or more, with up to two decimals.");
        }
        String policyDate = body == null || body.policyDate() == null ? null : body.policyDate().trim();
        if (policyDate != null && !policyDate.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policyDate).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The policy date must be a date (yyyy-mm-dd).");
            }
        }
        String numberingFrom = body == null || body.periodNumberingFrom() == null ? null : body.periodNumberingFrom().trim();
        if (numberingFrom != null && !numberingFrom.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numberingFrom).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The period numbering from-date must be a date (yyyy-mm-dd).");
            }
        }
        String cap = body == null || body.cap() == null ? null : body.cap().trim();
        if (cap != null && !cap.isEmpty()) {
            if (!AMOUNT.matcher(cap).matches()) {
